const nationalEnvironment='https://sites.google.com/edu-haifa.org.il/pilot-67/work-environment';
const nationalSections=[['nationalPeriod','תקופת התיעוד'],['nationalContext','מטרת התהליך והאתגר'],['nationalActions','מה עשינו בפועל'],['nationalEvidence','תוצרים וראיות להתקדמות'],['nationalLearning','תובנות, רפלקציה ולמידת עמיתים'],['nationalBarriers','חסמים והתאמות'],['nationalNext','הצעדים הבאים']];
document.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view="national">תיעוד ארצי</button>');
const nationalBanner=document.createElement('section');nationalBanner.className='nationalBanner';nationalBanner.setAttribute('aria-label','הסביבה הארצית לפיילוט 67/67');nationalBanner.innerHTML=`<span class="nationalIcon" aria-hidden="true">↗</span><div><b>המרחב הארצי · פיילוט 67/67</b><p>ניהול, תיעוד ולמידת עמיתים — מרכזים כאן את העשייה, ומכינים תיעוד לשיתוף.</p></div><div class="nationalBannerActions"><button data-view="national">הכנת טיוטת תיעוד</button><a href="${nationalEnvironment}" target="_blank" rel="noopener">פתיחת המרחב הארצי ↗</a></div>`;document.querySelector('.overview').before(nationalBanner);
function nationalDraft(){return ['טיוטת תיעוד פנימית — פיילוט 67/67','מרכז פסג״ה אזורי שפרעם','מבנה מוצע להכנה; אינו אישור הגשה למרחב הארצי.','',...nationalSections.flatMap(([key,title])=>[title,data.fields[key]||'טרם הוזן',''])].join('\n')}
const renderBeforeNational=render;
render=function(){renderBeforeNational();if(view==='national')$('content').innerHTML=`<div class="nationalHero"><span>מהעשייה המקומית ללמידה משותפת</span><h2>מכינים תיעוד למרחב הארצי</h2><p>מרכז פסג״ה אזורי שפרעם · פיילוט 67/67</p><a href="${nationalEnvironment}" target="_blank" rel="noopener">כניסה לסביבה הארצית ↗</a></div><div class="nationalSteps"><span><b>1</b> מתעדים את העשייה</span><span><b>2</b> בודקים ומדייקים</span><span><b>3</b> מעבירים ידנית למרחב הארצי</span></div><div class="nationalGuidance"><b>מתעדים תהליכים כדי ללמוד</b><p>בתיעוד המיועד לשיתוף התמקדו במהלך, בתוצרים ובדפוסי הפעולה. לפי ההנחיות הגלויות במרחב הארצי, יש להימנע משמות אישיים, פרטי קשר ומידע רגיש.</p><p>הטופס כאן הוא מבנה מוצע להכנה פנימית. טופסי המרחב הארצי המלאים דורשים כניסה ולא אומתו. אין סנכרון או שליחה אוטומטית.</p></div><h3>טיוטת התיעוד שלכם</h3><p class="nationalHint">מלאו רק מה שבוצע או תועד; אפשר לציין מה עדיין מתוכנן. הטיוטה נשמרת בדפדפן במכשיר זה.</p>${nationalSections.map(([key,title],i)=>field(title,key,i===0?'text':'textarea')).join('')}<div class="nationalDraftActions"><button id="previewNational" class="primary">הצגת הטיוטה</button><button id="downloadNational">↓ הורדת טיוטה כקובץ טקסט</button></div><label class="field nationalPreview">טיוטה לבדיקה לפני העברה<textarea id="nationalPreview" readonly rows="18">${esc(nationalDraft())}</textarea></label><p class="nationalHint">הורדת הקובץ אינה הגשה. להשלמת התיעוד, היכנסו למרחב הארצי והעבירו את הטקסט לשדות המתאימים.</p>`};
document.addEventListener('click',e=>{if(e.target.closest('#previewNational')){$('nationalPreview').value=nationalDraft();toast('הטיוטה עודכנה בהתאם לשדות שמילאתם')}if(e.target.closest('#downloadNational')){const url=URL.createObjectURL(new Blob(['\ufeff'+nationalDraft()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pilot67-national-draft.txt';a.click();URL.revokeObjectURL(url);toast('הטיוטה הורדה למכשיר — לא נשלחה למרחב הארצי')}});render();
